  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 12px;
  border-radius: var(--r-2);
  font-weight: 500; font-size: 13px;
  background: var(--accent); color: white;
  border: none;
}
.btn-primary:hover { filter: brightness(1.08); }

.searchbox {
  position: relative;
  display: inline-flex;
