.searchbox-hit-meta { font-size: 11px; color: var(--ink-4); font-family: var(--font-mono); margin-top: 2px; }
.searchbox-hit-snippet { font-size: 12px; color: var(--ink-3); margin-top: 4px; line-height: 1.4; }
.searchbox-empty { padding: 10px; font-size: 12px; color: var(--ink-4); text-align: center; }

.col-head-icon { display: inline-flex; color: var(--ink-3); margin-right: 2px; }

.error-banner {
  background: var(--t-bug-bg);
  color: var(--t-bug);
  padding: 6px 14px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}

.empty {
  padding: 18px;
  color: var(--ink-4);
  font-size: 13px;
  text-align: center;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 48px 24px;
  max-width: 520px;
  margin: 0 auto;
