  padding: 8px 16px;
  border-radius: var(--r-2);
  background: var(--accent);
  color: white;
  font-weight: 500;
  font-size: 13px;
  border: none;
}
.empty-state .cta:hover {
  background: oklch(0.45 0.135 280);
}
.empty-state .cta[disabled] {
  opacity: 0.5; cursor: not-allowed; background: var(--accent);
