/* Settings tab */
.settings {
  padding: 24px 28px 60px;
  overflow-y: auto;
  max-width: 720px;
}
.settings.empty { color: var(--ink-3); }
.settings-section { margin-bottom: 28px; }
.settings-section h3 {
  font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em;
