  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center; gap: 12px;
  padding: 6px 10px;
  margin: 8px 0 6px;
  background: var(--pivotal-iter-bar);
  color: var(--pivotal-iter-bar-fg);
  border-radius: var(--r-1);
  font-size: 12px;
}
