.iter-info { display: flex; flex-direction: column; gap: 1px; }
.iter-range { font-size: 12px; font-weight: 600; color: var(--pivotal-iter-bar-fg); }
.iter-sub { font-size: 10.5px; color: var(--pivotal-iter-bar-fg); opacity: 0.75; font-family: var(--font-mono); }
