  border-color: var(--pivotal-current-border);
}
.iter-current .story:hover {
  border-color: #C9C079;
  box-shadow: var(--shadow-1);
}

.story {
  position: relative;
  display: grid;
  grid-template-columns: 22px 1fr;
  gap: 10px;
  padding: 10px 12px;
  border-radius: var(--r-3);
  border: 1px solid transparent;
  margin-bottom: 4px;
  cursor: pointer;
  background: var(--bg-elev);
}
.story:hover { border-color: var(--line); box-shadow: var(--shadow-1); }
.story.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }
.story.is-icebox {
  background: oklch(0.96 0.025 230);
  border-color: oklch(0.86 0.05 230);
}
.story.is-icebox:hover { border-color: oklch(0.78 0.08 230); }
.story.is-icebox .story-title { color: oklch(0.32 0.06 235); }
/* Accepted stories (current iter or done) render with the success
   palette. No action buttons, no estimate pips. */
.story.is-accepted {
  background: oklch(0.95 0.05 145);
  border-color: oklch(0.78 0.10 145);
}
.story.is-accepted:hover { border-color: oklch(0.68 0.13 145); }
.story.is-accepted .story-title { color: oklch(0.30 0.10 145); }
.story.is-readonly { cursor: pointer; }
/* Epic chip: pill that names the story's epic. Shape echoes
   .label-chip (tags) but distinct: rounded pill, layer icon prefix,
   colored from the same epicColor() palette used by the Epics
   column cards so the link is visible. Clickable, single-click
   opens an epic filter column. */
.epic-chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 500;
  border: 1px solid var(--line-2);
  border-radius: 12px;
  background: var(--bg-soft);
  color: var(--ink-3);
  cursor: pointer;
  user-select: none;
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.epic-chip:hover { filter: brightness(0.96); }
.epic-chip svg { flex-shrink: 0; width: 11px; height: 11px; }

.story.add-row {
  grid-template-columns: 1fr;
}
.story.add-row input {
  width: 100%; border: none; outline: none;
  font-size: 13px; padding: 4px 6px; background: transparent;
}

.type-glyph {
  width: 22px; height: 22px;
  border-radius: 5px;
  display: grid; place-items: center;
  font-size: 14px; line-height: 1; flex: 0 0 auto;
  background: transparent;
}
/* Per-type tints only apply to the release flag SVG, since the
   feature/bug/chore glyphs now render an emoji and carry their own
   color information. */
.type-release { background: var(--t-release-bg); color: var(--t-release); }
.type-chip-emoji { margin-right: 2px; }

.story-body { min-width: 0; display: flex; flex-direction: column; gap: 7px; }
.story-row1 { display: flex; align-items: flex-start; gap: 10px; }
.story-title { flex: 1; min-width: 0; font-size: 13px; font-weight: 500; }
.story-points {
  font-family: var(--font-mono); font-size: 12px; font-weight: 600;
  padding: 1px 8px; border-radius: 4px;
  background: var(--bg-soft); border: 1px solid var(--line); color: var(--ink);
}
.story-points.unestimated { color: var(--ink-4); background: transparent; border-style: dashed; }
.story-row2 { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.story-meta { display: flex; align-items: center; gap: 4px; color: var(--ink-3); font-size: 11.5px; }
.label-chip { font-size: 11px; padding: 1px 7px; border-radius: 4px; background: var(--line-3); color: var(--ink-2); font-weight: 500; }

.state-pill { display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; font-weight: 600; }
.state-pill .dot { width: 6px; height: 6px; border-radius: 50%; }
.s-unstarted { color: var(--ink-4); }
.s-unstarted .dot { background: var(--ink-5); border: 1px solid var(--ink-4); box-sizing: border-box; }
.s-started { color: var(--st-started); }   .s-started .dot   { background: var(--st-started); }
.s-finished { color: var(--st-finished); } .s-finished .dot  { background: var(--st-finished); }
.s-delivered { color: var(--st-delivered); } .s-delivered .dot { background: var(--st-delivered); }
.s-accepted { color: var(--st-accepted); } .s-accepted .dot  { background: var(--st-accepted); }
.s-rejected { color: var(--st-rejected); } .s-rejected .dot  { background: var(--st-rejected); }

/* Release bar: a horizontal date stake, not a story card. Renders
   distinct from .story so it doesn't look like another row of work. */
.release-bar {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 12px;
  margin: 6px 0;
  border-radius: 4px;
  background: linear-gradient(90deg, oklch(0.94 0.10 80) 0%, oklch(0.96 0.06 80) 100%);
  border: 1px solid oklch(0.78 0.14 80);
  cursor: pointer;
  font-weight: 500;
}
.release-bar:hover { border-color: oklch(0.66 0.18 80); }
.release-bar.selected { box-shadow: 0 0 0 2px var(--accent-soft); }
.release-bar .release-flag {
  color: oklch(0.45 0.16 60);
  display: inline-flex; align-items: center;
}
.release-bar .release-title {
  flex: 1; min-width: 0;
  font-size: 13px;
  color: oklch(0.32 0.12 60);
}
.release-bar .release-date {
  font-family: var(--font-mono);
  font-size: 12px;
  color: oklch(0.40 0.14 60);
  padding: 2px 8px;
  background: oklch(1 0 0 / 0.5);
  border-radius: 12px;
}

.story.is-release {
  background: var(--t-release-bg);
  border-color: #BFE0C5;
  border-radius: var(--r-2);
  display: flex; align-items: center; gap: 8px; padding: 8px 12px;
}
.release-flag { color: var(--t-release); }
.story.is-release .story-title { font-weight: 600; color: var(--t-release); }

.avatar {
  width: 18px; height: 18px; border-radius: 50%;
  display: grid; place-items: center;
  color: white; font-family: var(--font-mono); font-size: 9px; font-weight: 600;
  flex: 0 0 auto;
}
.avatar-empty { width: 18px; height: 18px; border-radius: 50%; border: 1px dashed var(--line); flex: 0 0 auto; }
.story-blocked { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 600; color: var(--st-rejected); border: none; background: none; padding: 0; }

.btn-mini {
  font-size: 11.5px; font-weight: 600;
  padding: 2px 9px; border-radius: var(--r-1);
  border: 1px solid var(--line); background: var(--bg-elev);
  color: var(--ink-2); margin-left: auto; flex: 0 0 auto;
}
/* When buttons sit inside .story-actions the cluster takes the
   right-pin via margin-left:auto so the individual buttons can sit
   tight together with the cluster's own gap. Without this the second
   button reclaimed an auto-margin and Accept/Reject ended up at
   opposite ends of the row. */
.story-actions { display: flex; gap: 6px; margin-left: auto; flex: 0 0 auto; }
.story-actions .btn-mini { margin-left: 0; }
/* Card-level action buttons follow Pivotal Tracker conventions:
   forward-progress (Start/Finish/Deliver = .primary) is a uniform
   dark gray-brown; the PM verdict buttons get green (Accept) and
   red (Reject). Modal and Settings buttons override .primary to
   the accent purple so the dialog primary stands apart from the
   in-card progress button. */
.btn-mini.primary { background: var(--pivotal-btn-bg); color: var(--pivotal-btn-fg); border-color: var(--pivotal-btn-bg); }
.btn-mini.primary:hover { filter: brightness(1.15); }
.btn-mini.success { background: var(--pivotal-accept); color: white; border-color: var(--pivotal-accept); }
.btn-mini.success:hover { filter: brightness(1.08); }
.btn-mini.danger { background: var(--pivotal-reject); color: white; border-color: var(--pivotal-reject); }
.btn-mini.danger:hover { filter: brightness(1.08); }
.btn-mini[disabled] { opacity: 0.5; cursor: not-allowed; }

/* PM ceremony + reject reason inline panels */
.ceremony {
  background: var(--accent-soft);
  border: 1px solid var(--accent);
  border-radius: var(--r-3);
  padding: 14px;
  margin: 14px 0 18px;
}
.ceremony-head { font-weight: 600; font-size: 14px; margin-bottom: 10px; color: var(--ink); }
.ceremony-body { font-size: 13px; color: var(--ink-2); }
.ceremony-row { display: flex; gap: 8px; margin-bottom: 4px; }
.ceremony-label { font-family: var(--font-mono); font-size: 11px; color: var(--ink-3); text-transform: uppercase; letter-spacing: 0.06em; min-width: 84px; }
.ceremony-empty { font-size: 12.5px; color: var(--ink-4); padding: 6px 10px; background: var(--bg-soft); border-radius: var(--r-2); border: 1px dashed var(--line); margin-bottom: 12px; }
.ceremony-actions { display: flex; gap: 8px; margin-top: 12px; }
.reject-reason { width: 100%; min-height: 80px; font-family: var(--font-sans); font-size: 13px; padding: 8px 10px; border: 1px solid var(--line); border-radius: var(--r-2); margin: 8px 0; resize: vertical; }


/* Epics */
.epic-list { padding: 12px 14px 80px; overflow-y: auto; flex: 1; background: var(--bg-soft); }
.epic-card { border: 1px solid var(--line); border-radius: var(--r-3); padding: 14px; background: var(--bg-elev); margin-bottom: 8px; }
.epic-card-head { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }
.epic-color { width: 12px; height: 12px; border-radius: 3px; margin-top: 3px; background: var(--accent); flex: 0 0 auto; }
.epic-name { font-size: 14px; font-weight: 600; }
.epic-id { font-family: var(--font-mono); font-size: 11px; color: var(--ink-4); margin-top: 2px; }
.epic-progress { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.epic-progress-track { flex: 1; height: 6px; border-radius: 3px; background: var(--line); overflow: hidden; }
.epic-progress-fill { height: 100%; background: var(--accent); }
.epic-progress-pct { font-family: var(--font-mono); font-size: 11px; color: var(--ink-3); }
.epic-stack { display: flex; height: 4px; border-radius: 2px; overflow: hidden; margin-bottom: 8px; background: var(--line-2); }
.epic-stack-bar { height: 100%; }

.history-list { list-style: none; padding: 0; margin: 0; }
.history-entry {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "row1 hash" "subject hash";
  gap: 4px 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line-2);
  font-size: 12.5px;
}
.history-entry:last-child { border-bottom: none; }
.history-row1 { grid-area: row1; display: flex; gap: 8px; }
.history-author { font-weight: 500; color: var(--ink); }
.history-when { color: var(--ink-4); font-family: var(--font-mono); font-size: 11px; }
.history-subject { grid-area: subject; color: var(--ink-2); }
.history-hash { grid-area: hash; font-family: var(--font-mono); font-size: 11px; color: var(--ink-4); align-self: center; }
.epic-meta { display: flex; gap: 16px; font-family: var(--font-mono); font-size: 11px; color: var(--ink-3); flex-wrap: wrap; }
.epic-eta { color: var(--ink-2); }
.epic-eta.pending {
  color: oklch(0.50 0.12 60);
  font-style: italic;
}
.filter-header {
  margin: 6px 0 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}
.filter-header .epic-card { margin: 0; }

/* Detail panel */
.detail-overlay {
  position: fixed; inset: 0;
  background: rgba(15,15,14,0.18);
  opacity: 0; pointer-events: none;
  transition: opacity 0.18s;
  z-index: 50;
}
.detail-overlay.open { opacity: 1; pointer-events: auto; }
.detail-panel {
  position: fixed; top: 0; right: 0; bottom: 0;
  width: 480px; max-width: 92vw;
  background: var(--bg-panel);
  border-left: 1px solid var(--line);
  box-shadow: -16px 0 48px -16px rgba(15,15,14,0.18);
  transform: translateX(100%);
  transition: transform 0.22s ease;
  display: flex; flex-direction: column;
  z-index: 60;
}
.detail-panel.open { transform: translateX(0); }
.detail-head {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
}
.detail-body { flex: 1; overflow-y: auto; padding: 16px 18px 80px; }
.detail-title { font-size: 18px; font-weight: 600; margin: 0 0 12px; line-height: 1.3; }

.state-machine { display: flex; gap: 4px; margin-bottom: 16px; flex-wrap: wrap; }
.state-step {
  font-size: 11px; font-weight: 600; padding: 4px 8px; border-radius: var(--r-1);
  background: var(--line-3); color: var(--ink-3);
  border: 1px solid transparent; cursor: pointer;
}
.state-step:hover { border-color: var(--ink-4); }
.state-step.done { background: var(--bg-soft); color: var(--ink-2); }

/* Chip: the state-step that matches the story's current status.
   Solid fill in the state's accent + white text so the PM can see
   "you are here" at a glance. */
.state-step.current.s-unstarted { background: var(--st-unstarted); color: white; }
.state-step.current.s-started   { background: var(--st-started);   color: white; }
.state-step.current.s-finished  { background: var(--st-finished);  color: white; }
.state-step.current.s-delivered { background: var(--st-delivered); color: white; }
.state-step.current.s-accepted  { background: var(--st-accepted);  color: white; }
.state-step.current.s-rejected  { background: var(--st-rejected);  color: white; }

/* Button: the same state-step rendered as a transition target. Tinted
   text + matching border, no fill, so it reads as a clickable hint
   distinct from the solid chip. The color encodes the action verb
   per the design spec: start = gray, finish = blue (started chip
   color), deliver = orange (finished chip color), accept = green,
   reject = red. */
.state-step.s-unstarted:not(.current),
.state-step.s-started:not(.current)   { color: var(--st-unstarted); border-color: var(--st-unstarted); background: transparent; }
.state-step.s-finished:not(.current)  { color: var(--st-started);   border-color: var(--st-started);   background: transparent; }
.state-step.s-delivered:not(.current) { color: var(--st-finished);  border-color: var(--st-finished);  background: transparent; }
.state-step.s-accepted:not(.current)  { color: var(--st-accepted);  border-color: var(--st-accepted);  background: transparent; }
.state-step.s-rejected:not(.current)  { color: var(--st-rejected);  border-color: var(--st-rejected);  background: transparent; }

.field-grid {
  display: grid;
  grid-template-columns: 110px 1fr;
  row-gap: 10px; column-gap: 16px;
  font-size: 13px;
  margin-bottom: 18px;
}
.field-label { color: var(--ink-3); font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.04em; padding-top: 4px; }
.field-value { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.points-picker { display: inline-flex; gap: 2px; padding: 1px; border-radius: var(--r-2); background: var(--line-3); }
/* Type chooser in the detail panel field-grid. Tints each chip with
   the same per-type accent the TypeGlyph uses so feature/bug/chore
   are scannable. The non-active chips render flat; active gets the
   colored fill. */
.type-picker { display: inline-flex; gap: 6px; flex-wrap: wrap; }
.type-chip {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12.5px; font-weight: 500; text-transform: capitalize;
  padding: 5px 11px; border-radius: var(--r-2);
  border: 1px solid var(--line); background: var(--bg-elev);
  color: var(--ink-2); cursor: pointer;
  transition: border-color 80ms, background 80ms;
}
.type-chip:hover { border-color: var(--ink-4); }
/* Active state: a single neutral fill regardless of type. Type
   identity is carried by the emoji prefix; using the per-type
   status-adjacent colors here (brown, red, gray) made the chips
   compete with status pills for the same visual weight. */
.type-chip.active {
  background: var(--ink);
  color: white;
  border-color: var(--ink);
}
.type-chip-emoji { font-size: 13px; line-height: 1; }
/* Card-level pip row. Smaller than the detail-panel picker so the
   card stays single-line. Pinned right via margin-left:auto to mirror
   the read-only points label it replaced. */
.story-points-pips {
  display: inline-flex; gap: 1px; padding: 1px; margin-left: auto;
  border-radius: var(--r-2); background: var(--line-3);
  flex: 0 0 auto;
}
.story-points-pips .points-pip {
  width: 20px; height: 18px; font-size: 11px;
  cursor: pointer;
}
.story-points-pips .points-pip:hover { background: var(--line-2); color: var(--ink-2); }
.story-points-pips .points-pip.active { background: var(--ink); color: white; }
.story-points-pips .points-pip.active:hover { background: var(--ink); color: white; }
.points-pip {
  width: 26px; height: 24px; display: grid; place-items: center;
  font-family: var(--font-mono); font-size: 12px; font-weight: 600;
  border-radius: var(--r-1); color: var(--ink-3);
  border: none; background: transparent;
}
.points-pip.active { background: var(--ink); color: white; }
.inline-input {
  font-size: 13px; padding: 4px 8px;
  border: 1px solid var(--line); border-radius: var(--r-2);
  background: var(--bg-elev); color: var(--ink); min-width: 180px;
}
.owner-row { display: flex; gap: 4px; margin-top: 4px; }

.section-h { margin-top: 18px; margin-bottom: 8px; font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-3); display: flex; align-items: center; }
.tasks-list { display: flex; flex-direction: column; gap: 6px; margin-bottom: 8px; }
.task-row { display: flex; align-items: center; gap: 10px; }
.task-check {
  width: 18px; height: 18px; border-radius: 4px;
  border: 1px solid var(--line); background: var(--bg-elev);
  display: grid; place-items: center; color: white;
}
.task-check.done { background: var(--st-accepted); border-color: var(--st-accepted); }
.task-text { font-size: 13px; }
.task-text.done { text-decoration: line-through; color: var(--ink-4); }

.desc-view { white-space: pre-wrap; font-family: var(--font-mono); font-size: 12px; line-height: 1.5; background: var(--bg-soft); padding: 10px 12px; border-radius: var(--r-2); border: 1px solid var(--line); margin: 0; }
.desc-edit { width: 100%; min-height: 180px; font-family: var(--font-mono); font-size: 12px; line-height: 1.5; padding: 10px 12px; border: 1px solid var(--line); border-radius: var(--r-2); background: var(--bg-elev); color: var(--ink); resize: vertical; }

.comment { display: grid; grid-template-columns: 28px 1fr; gap: 10px; padding: 8px 0; border-top: 1px solid var(--line-2); }
.comment.add { padding-top: 12px; }
.comment-name { font-weight: 600; font-size: 12px; }
.comment-when { font-size: 11px; color: var(--ink-4); margin-left: 6px; font-family: var(--font-mono); }
.comment-body { font-size: 13px; color: var(--ink-2); margin-top: 2px; line-height: 1.5; }

/* Analytics */
.analytics { padding: 18px; overflow-y: auto; }
.analytics-grid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 12px;
}
.kpi-card {
  grid-column: span 3;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--r-3);
  padding: 14px;
}
.kpi-label { font-size: 11px; color: var(--ink-3); text-transform: uppercase; letter-spacing: 0.06em; font-weight: 600; }
.kpi-value { font-size: 30px; font-weight: 600; line-height: 1.1; margin-top: 6px; font-variant-numeric: tabular-nums; }
.kpi-unit { font-size: 14px; color: var(--ink-3); margin-left: 4px; }
.kpi-delta { font-size: 11px; color: var(--ink-4); margin-top: 4px; }

.chart-card {
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--r-3);
  padding: 14px;
}
.chart-card.span-7 { grid-column: span 7; }
.chart-card.span-5 { grid-column: span 5; }
.chart-title { font-weight: 600; font-size: 13px; }
.chart-sub { font-size: 11.5px; color: var(--ink-3); margin-top: 2px; }

.type-mix { margin-top: 12px; }
.type-mix-bar { display: flex; height: 16px; border-radius: 999px; overflow: hidden; background: var(--line-2); }
.type-mix-seg.type-feature { background: var(--t-feature); }
.type-mix-seg.type-bug { background: var(--t-bug); }
.type-mix-seg.type-chore { background: var(--t-chore); }
.type-mix-seg.type-release { background: var(--t-release); }
.type-mix-legend { margin-top: 12px; display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.type-mix-row { display: flex; align-items: center; gap: 8px; font-size: 12.5px; }
.type-mix-swatch { width: 14px; height: 14px; border-radius: 4px; }
.type-mix-swatch.type-feature { background: var(--t-feature); }
.type-mix-swatch.type-bug { background: var(--t-bug); }
.type-mix-swatch.type-chore { background: var(--t-chore); }
.type-mix-swatch.type-release { background: var(--t-release); }
.type-mix-label { font-weight: 500; flex: 1; }
.type-mix-count { font-family: var(--font-mono); font-weight: 600; }
.type-mix-pct { font-family: var(--font-mono); color: var(--ink-4); }

/* Search column form. The Search column lives in the user-toggled
   set (activity-bar tree) and renders its own multi-field form
   instead of relying on a top-bar input. */
.search-form {
  display: flex; flex-direction: column; gap: 6px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  background: var(--bg-soft);
}
.search-text {
  padding: 6px 8px;
  border: 1px solid var(--line-2);
  border-radius: 4px;
  font-size: 13px;
  background: var(--bg);
  color: var(--ink);
}
.search-text:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }
.search-label { font-size: 11px; color: var(--ink-3); margin-top: 4px; }
.search-select {
  padding: 5px 6px;
  border: 1px solid var(--line-2);
  border-radius: 4px;
  font-size: 12px;
  background: var(--bg);
  color: var(--ink);
}
.search-status-row { display: flex; flex-wrap: wrap; gap: 4px; }
.search-status-chip {
  display: inline-flex; align-items: center; gap: 3px;
  padding: 3px 6px;
  font-size: 11px;
  border: 1px solid var(--line-2);
  border-radius: 10px;
  background: var(--bg);
  cursor: pointer;
  user-select: none;
}
.search-status-chip input { display: none; }
.search-status-chip.on {
  background: var(--ink);
  color: var(--bg);
  border-color: var(--ink);
}
.search-clear {
  align-self: flex-start;
  margin-top: 6px;
}

/* Done column. Cards inside are all is-accepted so they pick up the
   success palette from the .story.is-accepted rule above. */
.col-done .col-body { padding-top: 0; }

/* Filter columns opened by double-clicking an epic or a tag chip. */
.col-filter .col-title {
  font-size: 13px;
  color: var(--ink-2);
}
.label-chip { cursor: pointer; }
.label-chip:hover { background: var(--accent-soft); }

/* VS Code dark theme rebalancing */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16181C;
    --bg-elev: #1F2125;
    --bg-soft: #1C1E22;
    --bg-panel: #1F2125;
    --ink: #ECECEA;
    --ink-2: #C5C5C0;
    --ink-3: #8E8E89;
    --ink-4: #6B6B66;
    --ink-5: #4A4A45;
    --line: #2E3137;
    --line-2: #25282E;
    --line-3: #20232A;
    --accent-soft: rgba(79,61,219,0.18);
  }
}
