\n  --accent: #4F3DDB;\n  --accent-soft: #ECEAFB;\n\n  --st-unstarted: #8A8A85; /* gray */\n  --st-started: #1F6FE5;   /* blue */\n  --st-finished: #D97706;  /* orange/amber */\n  --st-delivered: #0F0F0E; /* near-black */\n  --st-accepted: #15803D;  /* green */\n  --st-rejected: #B42318;  /* red */\n\n  /* Pivotal Tracker palette. Used for card backgrounds (yellow for\n     the current iteration band, white below the line), the\n     iteration-header strip, and the action buttons. The state-pill\n     colors above stay as-is for the detail panel's state-machine. */\n  --pivotal-current-bg:     #FFF8C8;  /* pale warm yellow */\n  --pivotal-current-border: #E8E1A4;\n  --pivotal-iter-bar:       #6F6C4E;  /* olive band header */\n  --pivotal-iter-bar-fg:    #F5F1D6;\n  --pivotal-btn-bg:         #4A4A48;  /* dark gray progress button */\n  --pivotal-btn-fg:         #F5F4EF;\n  --pivotal-accept:         #5BA85B;  /* green Accept button */\n  --pivotal-reject:         #D14747;  /* red Reject button */\n  --pivotal-star:           #E8B83C;  /* gold feature star */\n\n  --t-feature: #B45309;     --t-feature-bg: #FAEFD9;\n  --t-bug: #B42318;          --t-bug-bg: #FBE3DF;\n  --t-chore: #5C5C58;        --t-chore-bg: #ECECE8;\n  --t-release: #15803D;      --t-release-bg: #DEF1E2;\n\n  --r-1: 4px;\n  --r-2: 6px;\n  --r-3: 10px;\n  --r-4: 14px;\n\n  --shadow-1: 0 1px 1px rgba(15,15,14,0.04), 0 1px 2px rgba(15,15,14,0.04);\n  --shadow-2: 0 4px 12px -4px rgba(15,15,14,0.10), 0 1px 1px rgba(15,15,14,0.04);\n\n  --font-sans: ui-sans-serif, system-ui, -apple-system, sans-serif;\n  --font-mono: ui-monospace, monospace;\n}\n\n* { box-sizing: border-box; }\nhtml, body { margin: 0; padding: 0; height: 100%; }\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: var(--font-sans);\n  font-size: 14px;\n  line-height: 1.45;\n  -webkit-font-smoothing: antialiased;\n}\nbutton { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }\ninput, textarea { font-family: inherit; }\n\n#root { height: 100%; }\n\n.app {\n  display: grid;\n  grid-template-rows: 44px 1fr;\n  height: 100vh;\n  overflow: hidden;\n}\n\n.topbar {\n  display: flex; align-items: center; gap: 14px;\n  padding: 0 16px;\n  border-bottom: 1px solid var(--line);\n  background: var(--bg-elev);\n}\n.brand { display: flex; align-items: center; gap: 9px; font-weight: 600; }\n.brand-dot { width: 14px; height: 14px; border-radius: 4px; background: var(--ink); }\n.topbar-spacer { flex: 1; }\n\n.btn {\n  display: inline-flex; align-items: center; gap: 6px;\n  padding: 5px 10px;\n  border-radius: var(--r-2);\n  font-weight: 500; font-size: 13px;\n  border: 1px solid var(--line);\n  background: var(--bg-elev);\n  color: var(--ink-2);\n}\n.btn:hover { background: var(--bg-soft); }\n\n.btn-primary {\n  display: inline-flex; align-items: center; gap: 6px;\n  padding: 6px 12px;\n  border-radius: var(--r-2);\n  font-weight: 500; font-size: 13px;\n  background: var(--accent); color: white;\n  border: none;\n}\n.btn-primary:hover { filter: brightness(1.08); }\n\n.searchbox {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  background: var(--bg-soft);\n  border: 1px solid var(--line);\n  border-radius: var(--r-2);\n  padding: 4px 8px;\n  width: 280px;\n  margin-right: 8px;\n}\n.searchbox-icon { color: var(--ink-4); display: inline-flex; margin-right: 6px; }\n.searchbox-input {\n  flex: 1; border: none; outline: none; background: transparent;\n  font-size: 13px; color: var(--ink);\n}\n.searchbox-kbd {\n  font-family: var(--font-mono); font-size: 10.5px;\n  color: var(--ink-4);\n  padding: 1px 5px; border: 1px solid var(--line);\n  border-radius: 3px;\n}\n.searchbox-popover {\n  position: absolute;\n  top: calc(100% + 4px);\n  left: 0;\n  right: 0;\n  max-height: 360px;\n  overflow-y: auto;\n  background: var(--bg-elev);\n  border: 1px solid var(--line);\n  border-radius: var(--r-3);\n  box-shadow: var(--shadow-2);\n  padding: 4px;\n  z-index: 10;\n}\n.searchbox-hit {\n  display: block;\n  width: 100%; text-align: left;\n  padding: 8px 10px;\n  border-radius: var(--r-2);\n  background: transparent;\n  color: var(--ink);\n}\n.searchbox-hit:hover, .searchbox-hit.active { background: var(--bg-soft); }\n.searchbox-hit-title { font-size: 13px; font-weight: 500; }\n.searchbox-hit-meta { font-size: 11px; color: var(--ink-4); font-family: var(--font-mono); margin-top: 2px; }\n.searchbox-hit-snippet { font-size: 12px; color: var(--ink-3); margin-top: 4px; line-height: 1.4; }\n.searchbox-empty { padding: 10px; font-size: 12px; color: var(--ink-4); text-align: center; }\n\n.col-head-icon { display: inline-flex; color: var(--ink-3); margin-right: 2px; }\n\n.error-banner {\n  background: var(--t-bug-bg);\n  color: var(--t-bug);\n  padding: 6px 14px;\n  border-bottom: 1px solid var(--line);\n  font-size: 12px;\n}\n\n.empty {\n  padding: 18px;\n  color: var(--ink-4);\n  font-size: 13px;\n  text-align: center;\n}\n\n.empty-state {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 14px;\n  padding: 48px 24px;\n  max-width: 520px;\n  margin: 0 auto;\n  text-align: center;\n}\n.empty-state h2 {\n  margin: 0;\n  font-size: 18px;\n  font-weight: 600;\n  color: var(--ink);\n}\n.empty-state p {\n  margin: 0;\n  color: var(--ink-3);\n  font-size: 14px;\n  line-height: 1.55;\n}\n.empty-state .cta {\n  margin-top: 8px;\n  padding: 8px 16px;\n  border-radius: var(--r-2);\n  background: var(--accent);\n  color: white;\n  font-weight: 500;\n  font-size: 13px;\n  border: none;\n}\n.empty-state .cta:hover {\n  background: oklch(0.45 0.135 280);\n}\n.empty-state .cta[disabled] {\n  opacity: 0.5; cursor: not-allowed; background: var(--accent);\n}\n.empty-state-form { display: flex; gap: 8px; align-items: center; margin-top: 12px; }\n/* New-story modal. Centered overlay above the board so the\n   create-story flow is column-agnostic: the inline composer that\n   used to live in the Current column header implied stories would\n   land in Current, but `am create-item` actually stages into Icebox.\n   The modal states that up front. */\n.modal-overlay {\n  position: fixed; inset: 0; z-index: 999;\n  background: rgba(0, 0, 0, 0.35);\n  display: grid; place-items: center;\n  animation: am-modal-fade-in 120ms ease-out both;\n}\n@keyframes am-modal-fade-in {\n  from { opacity: 0; }\n  to   { opacity: 1; }\n}\n.modal-panel {\n  width: min(380px, calc(100vw - 32px));\n  min-width: 240px;\n  max-height: calc(100vh - 32px);\n  overflow-y: auto;\n  background: var(--bg-elev);\n  border: 1px solid var(--line);\n  border-radius: var(--r-3);\n  box-shadow: 0 10px 40px rgba(0,0,0,0.30);\n  padding: 16px 18px;\n  display: flex; flex-direction: column; gap: 12px;\n}\n.modal-head { display: flex; align-items: flex-start; gap: 8px; }\n.modal-title { font-size: 15px; font-weight: 600; color: var(--ink); line-height: 1.2; }\n.modal-subtitle { font-size: 12px; color: var(--ink-3); margin-top: 3px; }\n.modal-subtitle code { font-family: var(--font-mono); font-size: 11.5px; color: var(--ink-2); }\n.modal-head .icon-btn { margin-left: auto; flex: 0 0 auto; }\n.modal-body { display: flex; flex-direction: column; gap: 10px; }\n.modal-field { display: flex; flex-direction: column; gap: 5px; }\n.modal-label { font-family: var(--font-mono); font-size: 10.5px; color: var(--ink-3); text-transform: uppercase; letter-spacing: 0.06em; }\n/* Modal actions: Cancel left, primary right, 8px apart, both\n   right-edge-aligned. The selector below overrides .btn-mini's\n   default margin-left:auto (which was meant for card-row spacing\n   and was splitting our two buttons across the full row). */\n.modal-actions {\n  display: flex; gap: 8px;\n  justify-content: flex-end;\n  margin-top: 4px;\n}\n.modal-actions .btn-mini { margin-left: 0; padding: 6px 14px; font-size: 12.5px; }\n.modal-actions .btn-mini.primary {\n  background: var(--accent); color: white; border-color: var(--accent);\n}\n.modal-actions .btn-mini.primary:hover { filter: brightness(1.08); }\n.modal-actions .btn-mini.primary[disabled] { background: var(--ink-4); border-color: var(--ink-4); opacity: 1; }\n.empty-state-form .inline-input { min-width: 220px; }\n.empty-state-error { margin-top: 8px; font-size: 12px; color: var(--errorForeground, #c33); }\n\n.board {\n  display: flex;\n  align-items: stretch;\n  height: 100%;\n  overflow: hidden;\n  background: var(--bg);\n}\n/* Each visible column flexes to fill the available width. One\n   column visible = it spans the whole board. Three visible = they\n   share evenly. The min-width keeps cards readable on very narrow\n   webviews. */\n.board > .col { flex: 1 1 0; min-width: 280px; }\n.board > .col.epic-only { min-width: 240px; }\n\n.side {\n  border-right: 1px solid var(--line);\n  padding: 14px 12px;\n  overflow-y: auto;\n  background: var(--bg-elev);\n  display: flex; flex-direction: column; gap: 12px;\n}\n.side-section-title {\n  font-size: 10.5px; font-weight: 600;\n  color: var(--ink-4); letter-spacing: 0.06em;\n  text-transform: uppercase;\n  padding: 0 6px 6px;\n}\n.nav-item {\n  display: flex; align-items: center; gap: 10px;\n  padding: 6px 8px;\n  border-radius: var(--r-2);\n  font-size: 13px; color: var(--ink-2);\n  font-weight: 500;\n}\n.nav-item:hover { background: var(--bg-soft); cursor: pointer; }\n.nav-item.active { background: var(--accent-soft); color: var(--accent); }\n.nav-item-icon { display: inline-flex; color: var(--ink-3); }\n.nav-item.active .nav-item-icon { color: var(--accent); }\n.nav-item-label { flex: 1; }\n.nav-count {\n  font-family: var(--font-mono); font-size: 11px;\n  color: var(--ink-4); font-weight: 500;\n}\n\n\n.velocity-card {\n  background: var(--bg-soft);\n  border: 1px solid var(--line);\n  border-radius: var(--r-3);\n  padding: 12px;\n  margin-top: auto;\n}\n.velocity-num { font-size: 28px; font-weight: 600; line-height: 1; }\n.velocity-num small { font-size: 12px; color: var(--ink-3); margin-left: 4px; }\n.velocity-label { font-size: 10.5px; color: var(--ink-3); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 4px; font-weight: 600; }\n.velocity-foot { margin-top: 6px; font-size: 10.5px; color: var(--ink-4); font-family: var(--font-mono); }\n\n.col {\n  display: flex; flex-direction: column;\n  border-right: 1px solid var(--line);\n  min-height: 0;\n  background: var(--bg-soft);\n}\n.col:last-of-type { border-right: none; }\n.col-head {\n  display: flex; align-items: center; gap: 8px;\n  padding: 6px 14px;\n  /* Lock the header height to a single line regardless of whether\n     the column has an icon-button action. The Current column carries\n     a 28px tall `+` button while Icebox/Epics don't, and without a\n     min-height the column rows visibly disagreed on header height. */\n  min-height: 40px;\n  box-sizing: border-box;\n  border-bottom: 1px solid var(--line);\n  background: var(--bg-elev);\n}\n.col-title { font-weight: 600; font-size: 13px; }\n.col-meta { font-family: var(--font-mono); font-size: 11.5px; color: var(--ink-3); }\n.col-actions { margin-left: auto; display: flex; gap: 2px; }\n.icon-btn {\n  width: 28px; height: 28px;\n  display: grid; place-items: center;\n  border-radius: var(--r-2);\n  color: var(--ink-2);\n}\n.icon-btn:hover { background: var(--line-2); }\n\n/* col-add is the prominent + button on the Current and Icebox column\n   headers. Same accent-purple as the old \"Add story\" CTA so it reads\n   as a primary affordance, not a quiet icon button. */\n.col-add {\n  width: 26px; height: 26px;\n  display: grid; place-items: center;\n  border-radius: 999px;\n  background: var(--accent);\n  color: white;\n  border: none;\n  cursor: pointer;\n  box-shadow: 0 1px 4px rgba(79, 61, 219, 0.30);\n  transition: filter 80ms, transform 80ms;\n}\n.col-add:hover { filter: brightness(1.08); transform: scale(1.05); }\n.col-add:active { transform: scale(0.97); }\n\n/* Quiet X button on each column header. Removing a column hides it\n   from the board; the user can bring it back via the + Column\n   picker at the right edge. */\n.col-close {\n  width: 22px; height: 22px;\n  display: grid; place-items: center;\n  border-radius: 4px;\n  border: none; background: transparent;\n  color: var(--ink-4); cursor: pointer;\n}\n.col-close:hover { background: var(--line-2); color: var(--ink-2); }\n\n\n/* Empty state: no content columns visible AND no search query.\n   Sits centered in the board area with a card offering one-click\n   restores per available column. */\n.board-empty {\n  flex: 1;\n  display: grid; place-items: center;\n  background: var(--bg);\n}\n.board-empty-card {\n  background: var(--bg-elev);\n  border: 1px solid var(--line);\n  border-radius: var(--r-3);\n  padding: 28px 32px;\n  text-align: center;\n  max-width: 420px;\n  box-shadow: 0 4px 16px rgba(0,0,0,0.08);\n}\n.board-empty-title { font-size: 16px; font-weight: 600; color: var(--ink); margin-bottom: 4px; }\n.board-empty-sub { font-size: 13px; color: var(--ink-3); margin-bottom: 18px; }\n.board-empty-actions { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; }\n.board-empty-actions .btn-mini.primary {\n  background: var(--accent); color: white; border-color: var(--accent);\n  padding: 6px 12px;\n}\n\n/* Settings tab */\n.settings {\n  padding: 24px 28px 60px;\n  overflow-y: auto;\n  max-width: 720px;\n}\n.settings.empty { color: var(--ink-3); }\n.settings-section { margin-bottom: 28px; }\n.settings-section h3 {\n  font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em;\n  color: var(--ink-3); margin: 0 0 12px;\n  padding-bottom: 6px; border-bottom: 1px solid var(--line);\n}\n.settings-field {\n  display: grid;\n  grid-template-columns: 220px 1fr;\n  gap: 12px; align-items: center;\n  padding: 8px 0;\n}\n.settings-label { font-size: 13px; color: var(--ink-2); }\n.settings-value .inline-input { min-width: 180px; }\n.settings-value input[type=\"checkbox\"] { transform: scale(1.2); accent-color: var(--accent); }\n.settings-footer {\n  position: sticky; bottom: 0;\n  padding: 12px 0; margin-top: 8px;\n  background: linear-gradient(to bottom, transparent, var(--bg-panel) 40%);\n  display: flex; gap: 12px; align-items: center;\n}\n.settings-footer .btn-mini.primary {\n  background: var(--accent); color: white; border-color: var(--accent);\n  padding: 6px 14px; font-size: 12.5px;\n}\n.settings-footer .btn-mini.primary[disabled] { background: var(--ink-4); border-color: var(--ink-4); opacity: 1; cursor: not-allowed; }\n.settings-saved { font-size: 12px; color: var(--st-accepted); }\n.settings-hint {\n  font-size: 11.5px; color: var(--ink-4);\n  margin-top: 4px;\n  padding-left: 232px; /* align with the field-value column */\n}\n\n/* Autocomplete popover. Anchors below the input via the .autocomplete\n   wrapper; rendered while the input is focused AND there are matches.\n   Tab/Enter/click accepts the highlighted row. */\n.autocomplete { position: relative; display: inline-block; }\n.autocomplete .inline-input { width: 100%; }\n.autocomplete-pop {\n  position: absolute; top: calc(100% + 4px); left: 0;\n  min-width: 220px; max-width: 320px;\n  background: var(--bg-elev);\n  border: 1px solid var(--line);\n  border-radius: var(--r-2);\n  box-shadow: 0 6px 24px rgba(0,0,0,0.18);\n  padding: 4px;\n  z-index: 100;\n  display: flex; flex-direction: column;\n}\n.autocomplete-opt {\n  text-align: left;\n  font-size: 13px;\n  padding: 6px 10px;\n  border-radius: var(--r-1);\n  border: none;\n  background: transparent;\n  color: var(--ink-2);\n  cursor: pointer;\n}\n.autocomplete-opt:hover,\n.autocomplete-opt.active {\n  background: var(--accent-soft);\n  color: var(--ink);\n}\n.autocomplete-opt strong { color: var(--accent); font-weight: 600; }\n.autocomplete-opt.active strong { color: var(--accent); }\n.autocomplete-hint {\n  font-size: 10.5px;\n  color: var(--ink-4);\n  padding: 4px 10px 2px;\n  border-top: 1px solid var(--line-2);\n  margin-top: 2px;\n  font-family: var(--font-mono);\n}\n.icon-btn.detail-delete:hover { color: var(--errorForeground, #c33); }\n\n/* The \"Saving…\" toast appears fixed at top-center whenever writes\n   are in flight to the CLI. Bold and high-contrast so the click\n   acknowledgement is impossible to miss; floats above any column\n   layout so a narrow pane can't hide it. The minimum-visible window\n   is enforced from the useBusy hook, so fast writes still flash a\n   visible spinner. */\n/* Two-layer busy indicator. The thin progress bar at the top edge of\n   the webview is the YouTube/GitHub/Cursor convention; the pill below\n   it spells out what's happening. Both fire on the same useBusy flag\n   so they appear and clear together. */\n.busy-bar {\n  position: fixed; top: 0; left: 0; right: 0;\n  height: 3px;\n  z-index: 1001;\n  background: transparent;\n  overflow: hidden;\n  pointer-events: none;\n}\n.busy-bar::before {\n  content: '';\n  position: absolute; top: 0; bottom: 0;\n  width: 40%;\n  background: linear-gradient(90deg, transparent, var(--accent, #4F3DDB), transparent);\n  animation: am-bar 1.0s linear infinite;\n}\n@keyframes am-bar {\n  0%   { left: -40%; }\n  100% { left: 100%; }\n}\n\n.busy-pill {\n  position: fixed;\n  top: 14px; left: 50%; transform: translateX(-50%);\n  z-index: 1000;\n  display: inline-flex; align-items: center; gap: 10px;\n  font-size: 14px; font-weight: 700; color: white;\n  padding: 10px 20px; border-radius: 999px;\n  background: var(--accent, #4F3DDB);\n  box-shadow: 0 6px 20px rgba(79, 61, 219, 0.45), 0 2px 6px rgba(0,0,0,0.18);\n  font-family: var(--font-sans);\n  letter-spacing: 0.01em;\n  white-space: nowrap;\n  animation: am-fade-in 120ms ease-out both, am-pulse 1.4s ease-in-out infinite;\n  pointer-events: none;\n}\n.busy-pill .am-spinner { width: 16px; height: 16px; }\n.am-spinner { animation: am-spin 0.8s linear infinite; }\n@keyframes am-spin { to { transform: rotate(360deg); } }\n@keyframes am-fade-in { from { opacity: 0; transform: translate(-50%, -6px); } to { opacity: 1; transform: translate(-50%, 0); } }\n/* Subtle pulse so the pill draws the eye even when the CLI returns\n   fast. Stays within the minimum-visible window enforced by useBusy. */\n@keyframes am-pulse {\n  0%, 100% { box-shadow: 0 6px 20px rgba(79, 61, 219, 0.45), 0 2px 6px rgba(0,0,0,0.18); }\n  50%      { box-shadow: 0 6px 28px rgba(79, 61, 219, 0.75), 0 2px 8px rgba(0,0,0,0.25); }\n}\n.col-body {\n  overflow-y: auto;\n  padding: 8px 10px 80px;\n  flex: 1;\n}\n\n/* Pivotal-style iteration header: an olive bar at the top of each\n   iteration band with the date range and points total in light\n   type. Same color whether or not the band is the current one;\n   the yellow card-fill below differentiates current. */\n.iter-marker {\n  display: grid;\n  grid-template-columns: auto 1fr auto;\n  align-items: center; gap: 12px;\n  padding: 6px 10px;\n  margin: 8px 0 6px;\n  background: var(--pivotal-iter-bar);\n  color: var(--pivotal-iter-bar-fg);\n  border-radius: var(--r-1);\n  font-size: 12px;\n}\n.iter-marker:first-child { margin-top: 0; }\n.iter-num { font-size: 13px; font-weight: 700; line-height: 1; color: var(--pivotal-iter-bar-fg); font-variant-numeric: tabular-nums; }\n.iter-info { display: flex; flex-direction: column; gap: 1px; }\n.iter-range { font-size: 12px; font-weight: 600; color: var(--pivotal-iter-bar-fg); }\n.iter-sub { font-size: 10.5px; color: var(--pivotal-iter-bar-fg); opacity: 0.75; font-family: var(--font-mono); }\n.iter-progress { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--pivotal-iter-bar-fg); }\n.progress-track { position: relative; width: 70px; height: 4px; border-radius: 2px; background: rgba(255,255,255,0.2); overflow: hidden; }\n.progress-fill { position: absolute; left: 0; top: 0; bottom: 0; background: var(--pivotal-iter-bar-fg); border-radius: 2px; }\n\n/* Cards in the current iteration band wear the Pivotal yellow\n   background. Below-the-line stories keep the neutral panel color.\n   The .iter-current wrapper comes from the Board's bands.map(). */\n.iter-current .story {\n  background: var(--pivotal-current-bg);\n  border-color: var(--pivotal-current-border);\n}\n.iter-current .story:hover {\n  border-color: #C9C079;\n  box-shadow: var(--shadow-1);\n}\n\n.story {\n  position: relative;\n  display: grid;\n  grid-template-columns: 22px 1fr;\n  gap: 10px;\n  padding: 10px 12px;\n  border-radius: var(--r-3);\n  border: 1px solid transparent;\n  margin-bottom: 4px;\n  cursor: pointer;\n  background: var(--bg-elev);\n}\n.story:hover { border-color: var(--line); box-shadow: var(--shadow-1); }\n.story.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }\n.story.is-icebox {\n  background: oklch(0.96 0.025 230);\n  border-color: oklch(0.86 0.05 230);\n}\n.story.is-icebox:hover { border-color: oklch(0.78 0.08 230); }\n.story.is-icebox .story-title { color: oklch(0.32 0.06 235); }\n/* Accepted stories (current iter or done) render with the success\n   palette. No action buttons, no estimate pips. */\n.story.is-accepted {\n  background: oklch(0.95 0.05 145);\n  border-color: oklch(0.78 0.10 145);\n}\n.story.is-accepted:hover { border-color: oklch(0.68 0.13 145); }\n.story.is-accepted .story-title { color: oklch(0.30 0.10 145); }\n.story.is-readonly { cursor: pointer; }\n/* Epic chip: pill that names the story's epic. Shape echoes\n   .label-chip (tags) but distinct: rounded pill, layer icon prefix,\n   colored from the same epicColor() palette used by the Epics\n   column cards so the link is visible. Clickable, single-click\n   opens an epic filter column. */\n.epic-chip {\n  display: inline-flex; align-items: center; gap: 4px;\n  padding: 2px 8px;\n  font-size: 11px;\n  font-weight: 500;\n  border: 1px solid var(--line-2);\n  border-radius: 12px;\n  background: var(--bg-soft);\n  color: var(--ink-3);\n  cursor: pointer;\n  user-select: none;\n  max-width: 180px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.epic-chip:hover { filter: brightness(0.96); }\n.epic-chip svg { flex-shrink: 0; width: 11px; height: 11px; }\n\n.story.add-row {\n  grid-template-columns: 1fr;\n}\n.story.add-row input {\n  width: 100%; border: none; outline: none;\n  font-size: 13px; padding: 4px 6px; background: transparent;\n}\n\n.type-glyph {\n  width: 22px; height: 22px;\n  border-radius: 5px;\n  display: grid; place-items: center;\n  font-size: 14px; line-height: 1; flex: 0 0 auto;\n  background: transparent;\n}\n/* Per-type tints only apply to the release flag SVG, since the\n   feature/bug/chore glyphs now render an emoji and carry their own\n   color information. */\n.type-release { background: var(--t-release-bg); color: var(--t-release); }\n.type-chip-emoji { margin-right: 2px; }\n\n.story-body { min-width: 0; display: flex; flex-direction: column; gap: 7px; }\n.story-row1 { display: flex; align-items: flex-start; gap: 10px; }\n.story-title { flex: 1; min-width: 0; font-size: 13px; font-weight: 500; }\n.story-points {\n  font-family: var(--font-mono); font-size: 12px; font-weight: 600;\n  padding: 1px 8px; border-radius: 4px;\n  background: var(--bg-soft); border: 1px solid var(--line); color: var(--ink);\n}\n.story-points.unestimated { color: var(--ink-4); background: transparent; border-style: dashed; }\n.story-row2 { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n.story-meta { display: flex; align-items: center; gap: 4px; color: var(--ink-3); font-size: 11.5px; }\n.label-chip { font-size: 11px; padding: 1px 7px; border-radius: 4px; background: var(--line-3); color: var(--ink-2); font-weight: 500; }\n\n.state-pill { display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; font-weight: 600; }\n.state-pill .dot { width: 6px; height: 6px; border-radius: 50%; }\n.s-unstarted { color: var(--ink-4); }\n.s-unstarted .dot { background: var(--ink-5); border: 1px solid var(--ink-4); box-sizing: border-box; }\n.s-started { color: var(--st-started); }   .s-started .dot   { background: var(--st-started); }\n.s-finished { color: var(--st-finished); } .s-finished .dot  { background: var(--st-finished); }\n.s-delivered { color: var(--st-delivered); } .s-delivered .dot { background: var(--st-delivered); }\n.s-accepted { color: var(--st-accepted); } .s-accepted .dot  { background: var(--st-accepted); }\n.s-rejected { color: var(--st-rejected); } .s-rejected .dot  { background: var(--st-rejected); }\n\n/* Release bar: a horizontal date stake, not a story card. Renders\n   distinct from .story so it doesn't look like another row of work. */\n.release-bar {\n  display: flex; align-items: center; gap: 10px;\n  padding: 8px 12px;\n  margin: 6px 0;\n  border-radius: 4px;\n  background: linear-gradient(90deg, oklch(0.94 0.10 80) 0%, oklch(0.96 0.06 80) 100%);\n  border: 1px solid oklch(0.78 0.14 80);\n  cursor: pointer;\n  font-weight: 500;\n}\n.release-bar:hover { border-color: oklch(0.66 0.18 80); }\n.release-bar.selected { box-shadow: 0 0 0 2px var(--accent-soft); }\n.release-bar .release-flag {\n  color: oklch(0.45 0.16 60);\n  display: inline-flex; align-items: center;\n}\n.release-bar .release-title {\n  flex: 1; min-width: 0;\n  font-size: 13px;\n  color: oklch(0.32 0.12 60);\n}\n.release-bar .release-date {\n  font-family: var(--font-mono);\n  font-size: 12px;\n  color: oklch(0.40 0.14 60);\n  padding: 2px 8px;\n  background: oklch(1 0 0 / 0.5);\n  border-radius: 12px;\n}\n\n.story.is-release {\n  background: var(--t-release-bg);\n  border-color: #BFE0C5;\n  border-radius: var(--r-2);\n  display: flex; align-items: center; gap: 8px; padding: 8px 12px;\n}\n.release-flag { color: var(--t-release); }\n.story.is-release .story-title { font-weight: 600; color: var(--t-release); }\n\n.avatar {\n  width: 18px; height: 18px; border-radius: 50%;\n  display: grid; place-items: center;\n  color: white; font-family: var(--font-mono); font-size: 9px; font-weight: 600;\n  flex: 0 0 auto;\n}\n.avatar-empty { width: 18px; height: 18px; border-radius: 50%; border: 1px dashed var(--line); flex: 0 0 auto; }\n.story-blocked { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 600; color: var(--st-rejected); border: none; background: none; padding: 0; }\n\n.btn-mini {\n  font-size: 11.5px; font-weight: 600;\n  padding: 2px 9px; border-radius: var(--r-1);\n  border: 1px solid var(--line); background: var(--bg-elev);\n  color: var(--ink-2); margin-left: auto; flex: 0 0 auto;\n}\n/* When buttons sit inside .story-actions the cluster takes the\n   right-pin via margin-left:auto so the individual buttons can sit\n   tight together with the cluster's own gap. Without this the second\n   button reclaimed an auto-margin and Accept/Reject ended up at\n   opposite ends of the row. */\n.story-actions { display: flex; gap: 6px; margin-left: auto; flex: 0 0 auto; }\n.story-actions .btn-mini { margin-left: 0; }\n/* Card-level action buttons follow Pivotal Tracker conventions:\n   forward-progress (Start/Finish/Deliver = .primary) is a uniform\n   dark gray-brown; the PM verdict buttons get green (Accept) and\n   red (Reject). Modal and Settings buttons override .primary to\n   the accent purple so the dialog primary stands apart from the\n   in-card progress button. */\n.btn-mini.primary { background: var(--pivotal-btn-bg); color: var(--pivotal-btn-fg); border-color: var(--pivotal-btn-bg); }\n.btn-mini.primary:hover { filter: brightness(1.15); }\n.btn-mini.success { background: var(--pivotal-accept); color: white; border-color: var(--pivotal-accept); }\n.btn-mini.success:hover { filter: brightness(1.08); }\n.btn-mini.danger { background: var(--pivotal-reject); color: white; border-color: var(--pivotal-reject); }\n.btn-mini.danger:hover { filter: brightness(1.08); }\n.btn-mini[disabled] { opacity: 0.5; cursor: not-allowed; }\n\n/* PM ceremony + reject reason inline panels */\n.ceremony {\n  background: var(--accent-soft);\n  border: 1px solid var(--accent);\n  border-radius: var(--r-3);\n  padding: 14px;\n  margin: 14px 0 18px;\n}\n.ceremony-head { font-weight: 600; font-size: 14px; margin-bottom: 10px; color: var(--ink); }\n.ceremony-body { font-size: 13px; color: var(--ink-2); }\n.ceremony-row { display: flex; gap: 8px; margin-bottom: 4px; }\n.ceremony-label { font-family: var(--font-mono); font-size: 11px; color: var(--ink-3); text-transform: uppercase; letter-spacing: 0.06em; min-width: 84px; }\n.ceremony-empty { font-size: 12.5px; color: var(--ink-4); padding: 6px 10px; background: var(--bg-soft); border-radius: var(--r-2); border: 1px dashed var(--line); margin-bottom: 12px; }\n.ceremony-actions { display: flex; gap: 8px; margin-top: 12px; }\n.reject-reason { width: 100%; min-height: 80px; font-family: var(--font-sans); font-size: 13px; padding: 8px 10px; border: 1px solid var(--line); border-radius: var(--r-2); margin: 8px 0; resize: vertical; }\n\n\n/* Epics */\n.epic-list { padding: 12px 14px 80px; overflow-y: auto; flex: 1; background: var(--bg-soft); }\n.epic-card { border: 1px solid var(--line); border-radius: var(--r-3); padding: 14px; background: var(--bg-elev); margin-bottom: 8px; }\n.epic-card-head { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.epic-color { width: 12px; height: 12px; border-radius: 3px; margin-top: 3px; background: var(--accent); flex: 0 0 auto; }\n.epic-name { font-size: 14px; font-weight: 600; }\n.epic-id { font-family: var(--font-mono); font-size: 11px; color: var(--ink-4); margin-top: 2px; }\n.epic-progress { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }\n.epic-progress-track { flex: 1; height: 6px; border-radius: 3px; background: var(--line); overflow: hidden; }\n.epic-progress-fill { height: 100%; background: var(--accent); }\n.epic-progress-pct { font-family: var(--font-mono); font-size: 11px; color: var(--ink-3); }\n.epic-stack { display: flex; height: 4px; border-radius: 2px; overflow: hidden; margin-bottom: 8px; back